.fly-switch [id$="-row"] { display: flex; align-items: center; gap: 14px; }
.fly-switch [id$="-text"] { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.fly-switch [id$="-title"] { font: 600 15px/1.2 var(--display); }
.fly-switch [id$="-sub"] { font-size: 13px; color: var(--soft); }
.fly-switch [id$="-note"] { font-size: 12.5px; color: var(--mute); line-height: 1.5; margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--line); }
.fly-switch [id$="-note"]:empty { display: none; }

