  /* Room for a hovered card to lift and cast its shadow without being cut
     by the scroller's own edge, handed back as negative margin. */
  padding: 22px 2px 28px; margin: -22px -2px -28px;
  -webkit-mask-image: linear-gradient(90deg, #000 calc(100% - 56px), transparent);
}

/* The results grid is a scroller too: the same room for a hovered card. */
#search-results[data-view="store"] { padding: 22px 8px 34px 4px; margin-top: -16px; }

